"""
Self-contained bootstrap script generated from local src/
Reconstructs the full src/ package inside /kaggle/working/
"""
import os, sys, base64

ROOT = "/kaggle/working"
if ROOT not in sys.path:
    sys.path.insert(0, ROOT)

FILES = {
    "src/__init__.py": "DQo=",
    "src/data/__init__.py": "DQo=",
    "src/data/dataset.py": "",
    "src/data/transforms.py": "",
    "src/dataset.py": "",
    "src/detector.py": "",
    "src/engine/__init__.py": "DQo=",
    "src/engine/evaluator.py": "",
    "src/engine/target_assigner.py": "",
    "src/engine/trainer.py": "",
    "src/losses/__init__.py": "DQo=",
    "src/losses/multi_task_losses.py": "",
    "src/models/__init__.py": "DQo=",
    "src/models/backbone.py": "",
    "src/models/blocks.py": "",
    "src/models/detector.py": "",
    "src/models/head.py": "",
    "src/models/neck.py": "",
    "src/multi_task_losses.py": "",
    "src/utils/__init__.py": "DQo=",
    "src/utils/box_ops.py": "",
    "src/utils/checkpoint.py": "",
    "src/utils/logger.py": "",
}

for rel_path, b64_str in FILES.items():
    full_path = os.path.join(ROOT, rel_path)
    os.makedirs(os.path.dirname(full_path), exist_ok=True)
    with open(full_path, "wb") as f:
        f.write(base64.b64decode(b64_str))
    print(f"  [setup] wrote {rel_path}")

print("[✓] All src/ modules successfully unpacked to /kaggle/working/src/")
